<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('announcement.manage');verify_csrf();$pdo=staff_db();$me=current_staff();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO announcements(title,content,created_by,target_role_id,is_important,publish_at,expires_at,is_active) VALUES(?,?,?,?,?,?,?,1)")->execute([trim($_POST['title']),trim($_POST['content']),$me['id'],$_POST['target_role_id']?:null,isset($_POST['is_important'])?1:0,$_POST['publish_at']?:null,$_POST['expires_at']?:null]);staff_redirect('staff/admin/announcements-management.php');}$roles=$pdo->query("SELECT * FROM roles WHERE is_active=1 ORDER BY hierarchy_level")->fetchAll();$rows=$pdo->query("SELECT a.*,r.name target_role FROM announcements a LEFT JOIN roles r ON r.id=a.target_role_id ORDER BY a.created_at DESC")->fetchAll();$pageTitle='Manage Announcements';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Boss / Admin</p><h1>Manage announcements</h1></div></div><div class="split-grid"><section class="staff-panel"><form method="post"><?= csrf_field() ?><label>Title<input name="title" required></label><label>Audience<select name="target_role_id"><option value="">All staff</option><?php foreach($roles as $r):?><option value="<?= $r['id'] ?>"><?= h($r['name']) ?></option><?php endforeach;?></select></label><label>Content<textarea name="content" rows="6" required></textarea></label><label class="check"><input type="checkbox" name="is_important"> Important</label><div class="two"><label>Publish at<input type="datetime-local" name="publish_at"></label><label>Expires at<input type="datetime-local" name="expires_at"></label></div><button class="btn primary">Publish</button></form></section><section class="staff-panel table-panel"><table><thead><tr><th>Announcement</th><th>Audience</th><th>Important</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h($r['title']) ?></td><td><?= h($r['target_role']?:'All staff') ?></td><td><?= $r['is_important']?'Yes':'No' ?></td></tr><?php endforeach;?></tbody></table></section></div></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
